SINA_SMART["hemato1-rbc"] = {"lecture":"hemato1-rbc","title":"Red blood cells and erythropoiesis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-rbc:e0","text":"RBC: 4.5-5.5 million/mm³, no nucleus, 120 days.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e1","text":"Biconcave disc: 7-8 µm, MCV 85-95 fL.","topic":"Morphology and membrane","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e2","text":"Membrane: bilayer + cytoskeleton (spectrin, ankyrin, actin, 4.1).","topic":"Morphology and membrane","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e3","text":"Glycophorins carry antigens; band 3 transports anions.","topic":"Morphology and membrane","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e4","text":"Hereditary spherocytosis: cytoskeletal defect; splenectomy if symptomatic.","topic":"Morphology and membrane","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e5","text":"Hb: 2α + 2 non-α chains + 4 haems (Fe²⁺) → 4 O₂.","topic":"Haemoglobin","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e6","text":"HbA α₂β₂, HbF α₂γ₂, HbA2 α₂δ₂; α genes chr 16, β genes chr 11.","topic":"Haemoglobin","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e7","text":"Methaemoglobin (Fe³⁺) cannot carry O₂.","topic":"Haemoglobin","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e8","text":"Anaemia: Hb < 13 men, < 12 women, < 14.5 newborns.","topic":"Haemoglobin","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e10","text":"EPO from the kidney drives erythropoiesis; splenic macrophages remove old cells.","topic":"Metabolism, erythropoiesis and haemolysis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-rbc:e9","text":"Glycolysis 90% (pyruvate kinase, ATP); HMP shunt 10% (G6PD, NADPH, glutathione).","topic":"Metabolism, erythropoiesis and haemolysis","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1bgfnv3":"a","1fdnwbi":"a","5n4h3a":"a","1fg98nb":"a","125mgkf":"a","davb23":"a","bllhc9":"a","1mkg2ij":"a","1r7wub8":"a","1sx1jb9":"a","ijyepm":"a","mqgcci":"a","8umnrf":"a","1saggxh":"a","1eb85ld":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-rbc:e0":{"s":0,"u":["RBC: 4.5-5.5 million/mm³, no nucleus, 120 days.","They have no nucleus or organelles , so they cannot divide or synthesise proteins; they live about 120 days (half-life 28 days)."],"dp":[]},"hemato1-rbc:e1":{"s":1,"u":["Biconcave disc: 7-8 µm, MCV 85-95 fL.","A biconcave disc : diameter 7-8 µm , thickness 2.5 µm at the rim and 1 µm in the centre, volume 85-95 fL (MCV), surface about 140 µm², giving a large exchange surface."],"dp":[]},"hemato1-rbc:e2":{"s":1,"u":["Membrane: bilayer + cytoskeleton (spectrin, ankyrin, actin, 4.1).","The membrane is a lipid bilayer (phospholipids 65%, cholesterol 25%, glycolipids 10%) on a cytoskeleton.","Peripheral cytoskeletal proteins : spectrin, ankyrin, actin, protein 4.1 , which maintain shape and deformability (squeezing through capillaries under 3 µm)."],"dp":[]},"hemato1-rbc:e3":{"s":1,"u":["Glycophorins carry antigens; band 3 transports anions.","Integral proteins : glycophorins (carry blood-group antigens) and band 3 (anion transport)."],"dp":[]},"hemato1-rbc:e4":{"s":1,"u":["Hereditary spherocytosis: cytoskeletal defect; splenectomy if symptomatic.","Defects cause abnormal shapes: hereditary spherocytosis (the most common; treated by splenectomy when symptomatic), elliptocytosis, stomatocytosis."],"dp":[]},"hemato1-rbc:e5":{"s":2,"u":["Hb: 2α + 2 non-α chains + 4 haems (Fe²⁺) → 4 O₂.","A tetramer of 2 α-type and 2 non-α globin chains , each with a haem (protoporphyrin IX ring with ferrous Fe²⁺ ); each haem binds one O₂, so one Hb carries 4 O₂ .","In β-thalassaemia β chains are missing and HbF persists; it shows at about 6 months, when γ chains switch off."],"dp":[]},"hemato1-rbc:e6":{"s":2,"u":["HbA α₂β₂, HbF α₂γ₂, HbA2 α₂δ₂; α genes chr 16, β genes chr 11.","Types: HbA α₂β₂ , HbF α₂γ₂ , HbA2 α₂δ₂ . α-type genes on chromosome 16 , β-type on chromosome 11 ."],"dp":[]},"hemato1-rbc:e7":{"s":2,"u":["Methaemoglobin (Fe³⁺) cannot carry O₂.","Oxidised Fe³⁺ ( methaemoglobin ) cannot bind O₂."],"dp":[]},"hemato1-rbc:e8":{"s":2,"u":["Anaemia: Hb < 13 men, < 12 women, < 14.5 newborns.","Normal Hb: men 13-16 g/dL , women 12-15.5 , newborns 16.5-21.5 ; anaemia : Hb &lt; 13 (men), &lt; 12 (women), &lt; 14.5 (newborns)."],"dp":[]},"hemato1-rbc:e10":{"s":3,"u":["EPO from the kidney drives erythropoiesis; splenic macrophages remove old cells.","Erythropoiesis in the marrow: proerythroblast → basophilic, polychromatophilic and orthochromatic erythroblasts → reticulocyte → red cell, driven by erythropoietin (EPO) from the kidney in response to hypoxia, and needing iron, B12 and folate .","Physiological haemolysis : aged cells are taken up mainly by splenic macrophages ; haem → bilirubin (conjugated by the liver), iron recycled, globin → amino acids."],"dp":[]},"hemato1-rbc:e9":{"s":3,"u":["Glycolysis 90% (pyruvate kinase, ATP); HMP shunt 10% (G6PD, NADPH, glutathione).","Hexose monophosphate shunt (10%) : key enzyme G6PD , makes NADPH , which regenerates reduced glutathione protecting Hb and membrane from oxidation (G6PD deficiency → oxidative haemolysis).","Anaerobic glycolysis (Embden-Meyerhof, 90%) : 2 ATP per glucose (key enzyme pyruvate kinase ) for shape, flexibility and the cation pump, plus NADH to keep iron reduced."],"dp":[{"h":"Why G6PD deficiency causes haemolysis after fava beans","t":"Red cells cannot make new enzymes, so they depend on G6PD to produce NADPH and keep glutathione reduced. Oxidants from fava beans, some drugs or infection overwhelm cells lacking G6PD: haemoglobin oxidises and precipitates (Heinz bodies) and the membrane is damaged, so the spleen destroys the cells within days, causing anaemia and dark urine. Source: the lecture's hexose monophosphate shunt slides."}]}},"meta":{"1bgfnv3":{"a":"recall","vg":"hemato1-rbc:e10/recall/1"},"1fdnwbi":{"a":"relationship","vg":"hemato1-rbc:e0/relationship/1"},"5n4h3a":{"a":"recall","vg":"hemato1-rbc:e1/recall/1"},"1fg98nb":{"a":"recall","vg":"hemato1-rbc:e2/recall/1"},"125mgkf":{"a":"recall","vg":"hemato1-rbc:e3/recall/1"},"davb23":{"a":"recall","vg":"hemato1-rbc:e3/recall/2"},"bllhc9":{"a":"recall","vg":"hemato1-rbc:e6/recall/1"},"1mkg2ij":{"a":"recall","vg":"hemato1-rbc:e5/recall/1"},"1r7wub8":{"a":"recall","vg":"hemato1-rbc:e7/recall/1"},"1sx1jb9":{"a":"recall","vg":"hemato1-rbc:e8/recall/1"},"ijyepm":{"a":"recall","vg":"hemato1-rbc:e9/recall/1"},"mqgcci":{"a":"recall","vg":"hemato1-rbc:e9/recall/2"},"8umnrf":{"a":"recall","vg":"hemato1-rbc:e10/recall/2"},"1saggxh":{"a":"recall","vg":"hemato1-rbc:e10/recall/3"}},"explRev":"55ba0b825633"};
